let lut=[],cur=0;
function buildLut(t){const s=[hex(t.rust).map(v=>v*.7|0),hex(t.ink),hex(t.cream)];lut=[];
  for(let i=0;i<256;i++){const v=i/255,c=v<.5?mix(s[0],s[1],v*2):mix(s[1],s[2],(v-.5)*2);lut.push(`rgb(${c})`)}}
