// Scanline-dithered portrait (image comes from portrait.js)
const cv=$('#me'),W=cv.width,H=cv.height,ctx=cv.getContext('2d');
const SW=180,SH=200,CELL=W/SW;
const o=document.createElement('canvas');o.width=SW;o.height=SH;const g=o.getContext('2d',{willReadFrequently:true});
let px=new Uint8ClampedArray(SW*SH*4),f=0;
const img=new Image();
img.onload=()=>{g.drawImage(img,0,0,SW,SH);px=g.getImageData(0,0,SW,SH).data;paint(f)};
img.src=PORTRAIT;
const BAY=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5].map(v=>(v+.5)/16);
function paint(t){
  ctx.clearRect(0,0,W,H);
  const ST=2,CS=CELL*ST;
  for(let y=0;y<SH;y+=ST)for(let x=0;x<SW;x+=ST){
    let l=0;for(let dy=0;dy<ST;dy++)for(let dx=0;dx<ST;dx++)l+=px[((y+dy)*SW+x+dx)*4];
    l/=ST*ST*255;if(l<.1)continue;
    const r=Math.min(CS*.5,.45+Math.pow(l,1.25)*CS*.52+Math.sin(y*.6+t)*.1);
    ctx.fillStyle=lut[Math.round(l*255)];
    ctx.beginPath();ctx.arc(x*CELL+CS/2+(((y/ST)&1)?CS/2:0),y*CELL+CS/2,r,0,6.2832);ctx.fill();
  }
}
let saved=0;try{saved=+localStorage.getItem('theme')||0}catch(e){}
applyTheme(THEMES[saved]?saved:0);
setInterval(()=>paint(f+=.4),160);

