function beep(fq=660){if(muted)return;try{ac=ac||new AudioContext();if(ac.state==='suspended')ac.resume();const o=ac.createOscillator(),v=ac.createGain();
  o.type='square';o.frequency.value=fq;v.gain.value=.03;v.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+.08);
  o.connect(v);v.connect(ac.destination);o.start();o.stop(ac.currentTime+.08)}catch(e){}}
