// Boot screen
(function(){
  const boot=$('#boot'),bf=$('#bf'),bp=$('#bp'),press=$('#boot .press'),snd=$('#snd');
  const data=[['done','work.dir – selected work',PROJECTS.length+(PROJECTS.length===1?' project':' projects')],['done','story.log – my path',JOURNEY.length+(JOURNEY.length===1?' stop':' stops')],
    ['done','about.sys – about me','ready'],['done','hello.app – say hello','ready'],['wait','indexing files','0 / 4',4]];
  $('#boot .log').innerHTML=data.map(d=>`<div><span class="tg${d[0]==='warn'?' w':''}">${d[0]}</span><span>${d[1]}</span><span class="dots"></span><span class="v">${d[2]}</span></div>`).join('');
  const rows=$$('#boot .log div');
  let fast=false,ready=false,done=false;
  const sleep=ms=>new Promise(r=>setTimeout(r,fast?0:ms));
  function prog(p){const n=Math.round(p*100);bf.style.width=n+'%';bp.textContent=n+'%'}
  async function run(){
    await sleep(500);
    for(let i=0;i<rows.length;i++){
      const r=rows[i],n=data[i][3];
      r.classList.add('show');beep(440+i*40);
      if(n){for(let k=0;k<=n;k++){r.querySelector('.v').textContent=k+' / '+n;prog((i+k/n)/rows.length);await sleep(n>8?50:220)}r.querySelector('.tg').textContent='done'}
      prog((i+1)/rows.length);await sleep(380);
    }
    ready=true;press.classList.add('show');
  }
  function enter(){
    if(done)return;
    if(!ready){fast=true;return}
    done=true;boot.classList.add('out');setTimeout(()=>boot.remove(),700);beep(880);
  }
  addEventListener('keydown',e=>{
    if(done)return;
    if(e.key.toLowerCase()==='s'){act.mute();snd.textContent='[S] SOUND: '+(muted?'OFF':'ON');return}
    if(e.metaKey||e.ctrlKey||e.key==='Shift'||e.key==='Tab')return;
    enter();
  });
  boot.addEventListener('click',enter);
  run();
})();

// Reveal: the clear photo "prints" through halftone dots that swell under the cursor
(function(){
  const clr=$('#clear'),cx=clr.getContext('2d'),stage=$('#stage');
  const ST=2,CS=CELL*ST,GW=Math.ceil(SW/ST),GH=Math.ceil(SH/ST);
  const hd=document.createElement('canvas');hd.width=W;hd.height=H;
  const mk=document.createElement('canvas');mk.width=W;mk.height=H;const mc=mk.getContext('2d');
  const R=new Float32Array(GW*GH);
  let mx=-999,my=-999,on=false,run=false,ready=false;
  const RAD=58,EDGE=34;
  const him=new Image();
  him.onload=()=>{hd.getContext('2d').drawImage(him,0,0,W,H);ready=true};
  him.src=PORTRAIT_HD;
  function frame(){
    let moving=false;
    mc.clearRect(0,0,W,H);mc.fillStyle='#000';
    for(let j=0;j<GH;j++)for(let i=0;i<GW;i++){
      const k=j*GW+i,x=i*ST,y=j*ST;let t=0;
      if(on){const dx=x-mx,dy=y-my;t=Math.min(1,Math.max(0,(RAD-Math.sqrt(dx*dx+dy*dy))/EDGE))}
      const r=R[k],nr=t>r?Math.min(t,r+.2):Math.max(t,r-.05);
      R[k]=nr;if(Math.abs(nr-t)>.004)moving=true;
      if(nr>.01){mc.beginPath();mc.arc(x*CELL+CS/2+((j&1)?CS/2:0),y*CELL+CS/2,nr*CS*.78,0,6.2832);mc.fill()}
    }
    cx.globalCompositeOperation='source-over';cx.clearRect(0,0,W,H);cx.drawImage(hd,0,0);
    cx.globalCompositeOperation='destination-in';cx.drawImage(mk,0,0);cx.globalCompositeOperation='source-over';
    if(on||moving)requestAnimationFrame(frame);else run=false;
  }
  function kick(){if(!run){run=true;requestAnimationFrame(frame)}}
  stage.addEventListener('pointermove',e=>{
    const r=cv.getBoundingClientRect(),u=(e.clientX-r.left)/r.width,v=(e.clientY-r.top)/r.height;
    mx=u*SW;my=v*SH;
    on=ready&&u>=0&&u<1&&v>=0&&v<1&&Math.abs(((window.spinAngle||0)%360+540)%360-180)<3;
    stage.classList.toggle('hand',on&&px[(Math.floor(v*SH)*SW+Math.floor(u*SW))*4]>20);
    kick();
  });
  stage.addEventListener('pointerleave',()=>{on=false;stage.classList.remove('hand');kick()});
  window.revealOff=()=>{on=false;stage.classList.remove('hand');kick()};
})();

