// Scroll (wheel or touch drag) rotates the portrait, then it settles facing front
(function(){
  const stg=$('#stage');let a=0,t=0,idle,run=false;
  const calm=matchMedia('(prefers-reduced-motion:reduce)').matches;
  const off=v=>Math.abs(((v%360)+540)%360-180);
  function step(){
    a+=(t-a)*.12;if(Math.abs(t-a)<.05)a=t;
    window.spinAngle=a;stg.style.setProperty('--ry',a+'deg');
    if(off(a)>=3&&window.revealOff)window.revealOff();
    if(a!==t)requestAnimationFrame(step);else run=false;
  }
  function go(){if(!run){run=true;requestAnimationFrame(step)}}
  function push(d){
    if(calm||$('#screen').dataset.page!=='home'||$('#modal').classList.contains('show'))return;
    t+=d;clearTimeout(idle);idle=setTimeout(()=>{t=Math.round(t/360)*360;go()},600);go();
  }
  addEventListener('wheel',e=>push(e.deltaY*.3),{passive:true});
  let y0=null;
  addEventListener('touchstart',e=>{y0=e.touches[0].clientY},{passive:true});
  addEventListener('touchmove',e=>{const y=e.touches[0].clientY;if(y0!==null)push((y0-y)*.6);y0=y},{passive:true});
})();

// ===== Work page: halftone project gallery + detail panel =====
(function(){
  const scr=$('#screen'),field=$('#field'),proj=$('#proj'),pc=$('#pjc');
  const N=64,POS=[[14,12],[50,30],[26,54],[66,8],[8,50],[70,52]];
  const srcs=[],tiles=[];let cur=-1;
  const g0=document.createElement('canvas');g0.width=g0.height=N;
  const g=g0.getContext('2d',{willReadFrequently:true});
  const pad=v=>String(v).padStart(2,'0');
  const go=h=>{try{if(location.hash!==h)history.pushState(null,'',h||location.pathname+location.search)}catch(e){}};
  function proc(i){
    g.fillStyle='#000';g.fillRect(0,0,N,N);
    const bg=g.createRadialGradient(N*.5,N*.45,2,N*.5,N*.5,N*.7);bg.addColorStop(0,'#bbb');bg.addColorStop(1,'#222');
    g.fillStyle=bg;g.fillRect(0,0,N,N);
    if(i%2===0){
      g.fillStyle='#fff';g.fillRect(N*.14,N*.2,N*.72,N*.6);
      g.fillStyle='#555';g.fillRect(N*.14,N*.2,N*.72,N*.1);
      g.fillStyle='#333';for(let k=0;k<4;k++)g.fillRect(N*.2,N*.38+k*N*.08,N*(.36-k*.04),N*.035);
      g.fillStyle='#888';g.fillRect(N*.6,N*.38,N*.2,N*.3);
    }else{
      for(let k=0;k<6;k++){g.fillStyle=k%2?'#444':'#999';g.fillRect(0,k*N/6,N,N/12)}
      const s=g.createRadialGradient(N*.42,N*.4,2,N*.5,N*.5,N*.32);s.addColorStop(0,'#fff');s.addColorStop(1,'#222');
      g.fillStyle=s;g.beginPath();g.arc(N*.5,N*.5,N*.3,0,6.2832);g.fill();
    }
  }
  function draw(cv,i,k){
    const c=cv.getContext('2d'),cs=cv.width/N,s=srcs[i];
    c.clearRect(0,0,cv.width,cv.height);
    for(let y=0;y<N;y++)for(let x=0;x<N;x++){
      const l=s[(y*N+x)*4]/255;if(l<.06)continue;
      const r=Math.min(cs*.74,(l*cs*.6+.4)*(.85+.35*k));
      c.fillStyle=lut[Math.round(l*255)];
      c.beginPath();c.arc(x*cs+cs/2+((y&1)?cs/2:0),y*cs+cs/2,r,0,6.2832);c.fill();
    }
  }
  function tween(t,i){
    if(t.run)return;t.run=true;
    (function f(){t.k+=(t.t-t.k)*.2;if(Math.abs(t.t-t.k)<.02)t.k=t.t;draw(t.c,i,t.k);
      if(t.k!==t.t)requestAnimationFrame(f);else t.run=false})();
  }
  let shotList=[],shotI=0;
  function setShot(k){
    shotI=k;const s=shotList[k],im=$('#gmain img');
    im.src=s.src;im.alt=s.caption;$('#gcap').textContent=pad(k+1)+' / '+pad(shotList.length)+' · '+s.caption;
    [...$('#gth').children].forEach((t,j)=>t.classList.toggle('on',j===k));
  }
  const lb=$('#lb');
  function lbShow(k){
    const n=shotList.length;shotI=(k+n)%n;const s=shotList[shotI];
    $('#lbi').src=s.src;$('#lbi').alt=s.caption;$('#lbc').textContent=pad(shotI+1)+' / '+pad(n)+' · '+s.caption;
    lb.classList.add('show');
  }
  function lbHide(){lb.classList.remove('show');setShot(shotI)}
  $('#gmain').onclick=()=>lbShow(shotI);
  $('#lbx').onclick=lbHide;$('#lbp').onclick=()=>lbShow(shotI-1);$('#lbn').onclick=()=>lbShow(shotI+1);
  lb.addEventListener('click',e=>{if(e.target===lb)lbHide()});
  addEventListener('keydown',e=>{
    if(!lb.classList.contains('show'))return;
    if(e.key==='Escape'){lbHide();e.stopImmediatePropagation()}
    else if(e.key==='ArrowRight'){lbShow(shotI+1);e.stopImmediatePropagation()}
    else if(e.key==='ArrowLeft'){lbShow(shotI-1);e.stopImmediatePropagation()}
  },true);
  function openP(i){
    cur=i;const p=PROJECTS[i];
    $('#pjn').textContent=pad(i+1)+' / '+pad(PROJECTS.length);
    $('#pjt').textContent=p.title;
    $('#pjk').textContent=[p.tag,p.year].filter(Boolean).join(' · ');
    $('#pjd').textContent=p.about;
    const dl=$('#pjl');dl.innerHTML='';
    [['Role',p.role],['Stack',p.stack]].forEach(([k,v])=>{if(!v)return;const a=document.createElement('dt'),b=document.createElement('dd');a.textContent=k;b.textContent=v;dl.append(a,b)});
    const a=$('#pja');if(p.link){a.href=p.link;a.hidden=false}else a.hidden=true;
    const gal=$('#pjg');
    if(p.shots&&p.shots.length){
      shotList=p.shots.map(s=>({src:SHOTS[s[0]],caption:s[1]}));
      const th=$('#gth');th.innerHTML='';
      shotList.forEach((s,j)=>{const b=document.createElement('button'),im=new Image();b.type='button';im.src=s.src;im.alt='';b.appendChild(im);b.setAttribute('aria-label','Screenshot '+(j+1));b.onclick=()=>setShot(j);th.appendChild(b)});
      gal.hidden=false;pc.hidden=true;setShot(0);
    }else{gal.hidden=true;pc.hidden=false;draw(pc,i,1)}
    $('#cbp').textContent=' / '+p.title.toLowerCase().replace(/\s+/g,'-');
    proj.classList.add('open');proj.setAttribute('aria-hidden','false');field.classList.add('dim');
    if(!calm)[...proj.querySelector('.in').children].forEach((el,k)=>el.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'none'}],{duration:400,delay:140+k*60,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'}));
    go('#work/'+(i+1));
  }
  function closeP(push=true){
    cur=-1;proj.classList.remove('open');proj.setAttribute('aria-hidden','true');
    field.classList.remove('dim');$('#cbp').textContent='';if(push)go('#work');
  }
  PROJECTS.forEach((p,i)=>{
    const b=document.createElement('button'),pos=POS[i%POS.length];
    b.className='tile';b.style.left=pos[0]+'%';b.style.top=pos[1]+'%';b.style.animationDelay=(-i*1.7)+'s';
    b.innerHTML='<canvas width="320" height="320"></canvas><span class="tt"><span class="tname"></span><span class="tn"></span></span>';
    b.querySelector('.tname').textContent=p.title;b.querySelector('.tn').textContent=pad(i+1);
    const t={b,c:b.querySelector('canvas'),k:0,t:0,run:false};tiles.push(t);
    const on=()=>{t.t=1;tween(t,i)},off=()=>{t.t=0;tween(t,i)};
    b.addEventListener('pointerenter',on);b.addEventListener('pointerleave',off);b.addEventListener('focus',on);b.addEventListener('blur',off);
    b.addEventListener('click',()=>openP(i));
    proc(i);srcs[i]=g.getImageData(0,0,N,N).data.slice();draw(t.c,i,0);
    if(p.img){const im=new Image();im.onload=()=>{
      const s=Math.max(N/im.width,N/im.height),w=im.width*s,h=im.height*s;
      g.fillStyle='#000';g.fillRect(0,0,N,N);g.drawImage(im,(N-w)/2,(N-h)/2,w,h);
      const d=g.getImageData(0,0,N,N).data.slice();for(let k=0;k<d.length;k+=4)d[k]=(d[k]+d[k+1]+d[k+2])/3;
      srcs[i]=d;draw(t.c,i,t.k);if(cur===i)draw(pc,i,1)};im.src=p.img}
    field.appendChild(b);
  });
  $('#wnote').textContent=PROJECTS.length+(PROJECTS.length===1?' project':' projects')+' · more on the way';
  field.addEventListener('pointermove',e=>{
    const r=field.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;
    tiles.forEach((t,i)=>{const d=(i%2?-1:1)*(14+i*4);t.b.style.transform='translate('+x*d+'px,'+y*d+'px)'});
  });
  field.addEventListener('click',e=>{if(cur>=0&&e.target===field)closeP()});
  $('#pjx').onclick=()=>closeP();
  window.onTheme=()=>{tiles.forEach((t,i)=>draw(t.c,i,t.k));if(cur>=0)draw(pc,cur,1)};
  const calm=matchMedia('(prefers-reduced-motion:reduce)').matches;
  let busy=false,pend=null;
  function setPage(p,instant){
    if(busy){pend=p;return}
    if(scr.dataset.page===p)return;
    const pg={home:$('.stage'),work:$('#work'),journey:$('#journey'),about:$('#about'),hello:$('#hello')},out=pg[scr.dataset.page],inn=pg[p];
    if(instant||calm||!out.animate){scr.dataset.page=p;return}
    busy=true;
    const a=out.animate([{opacity:1,transform:'none',filter:'blur(0px)'},{opacity:0,transform:'scale('+(p==='home'?.97:1.04)+')',filter:'blur(6px)'}],{duration:260,easing:'cubic-bezier(.4,0,.8,.4)',fill:'forwards'});
    a.onfinish=()=>{
      scr.dataset.page=p;a.cancel();
      const b=inn.animate([{opacity:0,transform:'translateY(16px) scale(.985)',filter:'blur(6px)'},{opacity:1,transform:'none',filter:'blur(0px)'}],{duration:440,easing:'cubic-bezier(.2,.8,.2,1)'});
      if(p==='journey')$$('.jst').forEach((b,i)=>b.animate([{opacity:0,translate:'0 20px'},{opacity:1,translate:'0 0'}],{duration:480,delay:120+i*90,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'}));
      if(p==='work')tiles.forEach((t,i)=>t.b.animate([{opacity:0,translate:'0 30px'},{opacity:1,translate:'0 0'}],{duration:520,delay:140+i*110,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'}));
      b.onfinish=()=>{busy=false;if(pend&&pend!==scr.dataset.page){const q=pend;pend=null;setPage(q)}else pend=null};
    };
  }
  window.setPage=setPage;
  window.closeProj=()=>{if(cur>=0)closeP(false)};
  // navigation
  window.openWork=()=>{closeMenus();setPage('work');go('#work')};
  window.closeWork=()=>{if(cur>=0)closeP(false);setPage('home');go('')};
  $('#home').onclick=()=>{closeMenus();if(scr.dataset.page==='work')window.closeWork()};
  addEventListener('keydown',e=>{
    if(e.key!=='Escape'||scr.dataset.page!=='work')return;
    if(document.getElementById('boot'))return;
    if(cur>=0)closeP();else window.closeWork();
  });
  function route(instant){
    const h=location.hash,m=h.match(/^#work\/(\d+)/);
    if(h.indexOf('#work')===0){setPage('work',instant);if(m&&PROJECTS[m[1]-1])openP(+m[1]-1);else if(cur>=0)closeP(false)}
    else if(h.indexOf('#journey')===0){if(cur>=0)closeP(false);window.routeJourney&&window.routeJourney(instant)}
    else if(h.indexOf('#about')===0){if(cur>=0)closeP(false);window.routeAbout&&window.routeAbout(instant)}
    else if(h.indexOf('#hello')===0){if(cur>=0)closeP(false);window.routeHello&&window.routeHello(instant)}
    else{if(cur>=0)closeP(false);setPage('home',instant)}
  }
  addEventListener('popstate',()=>route());route(true);
})();

// ===== Theme change plays a CRT power-off / power-on animation =====
let tvBusy=false;
const tvLine=document.createElement('div');tvLine.id='tvline';document.documentElement.appendChild(tvLine);
function sweep(f0,f1,d){
  if(muted)return;
  try{ac=ac||new AudioContext();if(ac.state==='suspended')ac.resume();
    const t=ac.currentTime,o=ac.createOscillator(),v=ac.createGain();
    o.type='sawtooth';o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(f1,t+d);
    v.gain.setValueAtTime(.04,t);v.gain.exponentialRampToValueAtTime(.0001,t+d);
    o.connect(v);v.connect(ac.destination);o.start();o.stop(t+d);
  }catch(e){}
}
function changeTheme(i){
  if(i===cur||tvBusy)return;
  const html=document.documentElement,body=document.body;
  if(matchMedia('(prefers-reduced-motion:reduce)').matches||!body.animate){applyTheme(i);return}
  tvBusy=true;html.classList.add('tv');
  const F='inset(0% 0% 0% 0%)',L='inset(49.7% 0% 49.7% 0%)',D='inset(49.7% 49.8% 49.7% 49.8%)';
  sweep(900,60,.42);
  const off=body.animate([{clipPath:F},{offset:.6,clipPath:L},{clipPath:D}],{duration:420,easing:'cubic-bezier(.55,0,.8,.4)',fill:'forwards'});
  tvLine.animate([{opacity:0,width:'100vw'},{offset:.55,opacity:0,width:'100vw'},{offset:.62,opacity:1,width:'100vw'},{offset:.9,opacity:1,width:'10px'},{opacity:1,width:'4px'}],{duration:420,fill:'forwards'});
  off.onfinish=()=>{
    applyTheme(i);
    setTimeout(()=>{
      sweep(80,700,.5);
      body.animate([{clipPath:D},{offset:.38,clipPath:L},{clipPath:F}],{duration:520,easing:'cubic-bezier(.2,.6,.3,1)',fill:'forwards'});
      const on=tvLine.animate([{opacity:1,width:'4px'},{offset:.35,opacity:1,width:'100vw'},{offset:.6,opacity:1,width:'100vw'},{opacity:0,width:'100vw'}],{duration:520,fill:'forwards'});
      on.onfinish=()=>{body.getAnimations().forEach(a=>a.cancel());tvLine.getAnimations().forEach(a=>a.cancel());html.classList.remove('tv');tvBusy=false};
    },140);
  };
}

// ===== Journey page: route-map timeline =====
(function(){
  const scr=$('#screen'),trk=$('#jtrack'),sts=[],n=JOURNEY.length;let sel=0;
  const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
  const pad=v=>String(v).padStart(2,'0');
  const go=h=>{try{if(location.hash!==h)history.pushState(null,'',h||location.pathname+location.search)}catch(e){}};
  JOURNEY.forEach((j,i)=>{
    const b=document.createElement('button');b.className='jst';b.style.left=(n>1?i/(n-1)*100:50)+'%';
    b.innerHTML='<i></i><span class="y"></span><span class="k"></span>';
    b.querySelector('.y').textContent=j.year;b.querySelector('.k').textContent=j.kind||'';
    b.setAttribute('aria-label',j.title);b.onclick=()=>pick(i);trk.appendChild(b);sts.push(b);
  });
  function pick(i,push=true){
    i=Math.max(0,Math.min(n-1,i));sel=i;const j=JOURNEY[i];
    sts.forEach((b,k)=>b.classList.toggle('on',k===i));
    $('#jfill').style.width=(n>1?i/(n-1)*100:0)+'%';
    $('#jmeta').textContent=[j.dates||(j.year+(j.end?' – '+j.end:'')),j.kind].filter(Boolean).join(' · ');
    $('#jtitle').textContent=j.title;$('#jplace').textContent=j.place||'';const ab=$('#jabout');ab.textContent=j.about||'';ab.hidden=!j.about;
    const ul=$('#jpts');ul.innerHTML='';(j.points||[]).forEach(t=>{const li=document.createElement('li');li.textContent=t;ul.appendChild(li)});
    const tg=$('#jtags');tg.innerHTML='';
    (j.tags||[]).forEach(t=>{const s=document.createElement('span');s.textContent=t;tg.appendChild(s)});
    $('#jghost').textContent=j.year;$('#jc').textContent=pad(i+1)+' / '+pad(n);
    $('#jp').disabled=i===0;$('#jn').disabled=i===n-1;$('#cbj').textContent=' / '+pad(i+1);
    if(!reduced)[...$('#jdet').children].forEach((el,k)=>el.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'none'}],{duration:380,delay:k*45,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'}));
    if(push&&scr.dataset.page==='journey')go('#journey/'+(i+1));
  }
  const goHome=()=>{window.setPage('home');go('')};
  window.openJourney=()=>{closeMenus();window.setPage('journey');go('#journey/'+(sel+1))};
  window.routeJourney=instant=>{
    window.setPage('journey',instant);
    const m=location.hash.match(/^#journey\/(\d+)/);pick(m?+m[1]-1:sel,false);
  };
  $('#jp').onclick=()=>pick(sel-1);$('#jn').onclick=()=>pick(sel+1);
  $('#home').addEventListener('click',()=>{if(scr.dataset.page==='journey')goHome()});
  addEventListener('keydown',e=>{
    if(scr.dataset.page!=='journey'||document.getElementById('boot'))return;
    if(e.key==='ArrowRight')pick(sel+1);else if(e.key==='ArrowLeft')pick(sel-1);else if(e.key==='Escape')goHome();
  });
  const og=document.getElementById('orbmarks');
  if(og){
    og.insertAdjacentHTML('beforeend',JOURNEY.map((j,i)=>{
      const a=(n>1?165-140*i/(n-1):95)*Math.PI/180,x=300+250*Math.cos(a),y=205+62*Math.sin(a);
      return '<g transform="translate('+x.toFixed(1)+','+y.toFixed(1)+')"><g class="pb" style="animation-delay:-'+(i*.6).toFixed(1)+'s"><g class="pin" style="transition-delay:'+(.05+i*.07).toFixed(2)+'s"><rect class="dm" x="-6" y="-6" width="12" height="12" transform="rotate(45)"/><text y="-14"></text></g></g></g>';
    }).join(''));
    og.querySelectorAll('text').forEach((t,i)=>{t.textContent=JOURNEY[i].year});
  }
  pick(0,false);
  if(location.hash.indexOf('#journey')===0)window.routeJourney(true);
})();

