// ===== Hello page: message form + links =====
(function(){
  const scr=$('#screen'),K=CONTACT;
  const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
  const go=h=>{try{if(location.hash!==h)history.pushState(null,'',h||location.pathname+location.search)}catch(e){}};
  const to=$('#h-to');to.textContent=K.email;to.href='mailto:'+K.email;$('#h-note').textContent=K.note;
  [['@','Email',K.email,'mailto:'+K.email],['</>','GitHub',K.github,'https://'+K.github],['in','LinkedIn',K.linkedin,'https://'+K.linkedin]].forEach(r=>{
    const a=document.createElement('a');a.href=r[3];if(r[3].indexOf('http')===0){a.target='_blank';a.rel='noopener'}
    a.innerHTML='<i></i><span><b></b><em></em></span>';
    a.querySelector('i').textContent=r[0];a.querySelector('b').textContent=r[1];a.querySelector('em').textContent=r[2];
    $('#h-links').appendChild(a);
  });
  const st=$('#h-status');
  $('#h-send').onclick=()=>{
    const from=$('#h-from').value.trim(),subj=$('#h-subj').value.trim()||'Message from your portfolio',msg=$('#h-msg').value.trim();
    if(!msg){st.textContent='Please write a message first.';$('#h-msg').focus();return}
    const lines=[msg,'','—'];
    if(from)lines.push('From: '+from);
    if($('#h-proj').value)lines.push('Project type: '+$('#h-proj').value);
    if($('#h-time').value)lines.push('Timeline: '+$('#h-time').value);
    const body=lines.join('\n');
    try{navigator.clipboard.writeText('To: '+K.email+'\nSubject: '+subj+'\n\n'+body).catch(()=>{})}catch(e){}
    st.textContent='Opening your email app… if nothing happens, the message was copied: paste it into an email to '+K.email+'.';
    location.href='mailto:'+K.email+'?subject='+encodeURIComponent(subj)+'&body='+encodeURIComponent(body);
  };
  $('#h-copy').onclick=()=>{
    const b=$('#h-copy');
    const done=ok=>{b.textContent=ok?'copied ✓':'press Ctrl+C on the address above';setTimeout(()=>{b.textContent='copy email address'},1800)};
    try{navigator.clipboard.writeText(K.email).then(()=>done(true),()=>done(false))}catch(e){done(false)}
  };
  function intro(){
    if(reduced)return;
    [$('.hform'),$('.hside')].forEach((el,k)=>el.animate([{opacity:0,transform:'translateY(16px)'},{opacity:1,transform:'none'}],{duration:480,delay:300+k*120,easing:'cubic-bezier(.2,.8,.2,1)',fill:'backwards'}));
  }
  const goHome=()=>{window.setPage('home');go('')};
  window.openHello=()=>{closeMenus();window.setPage('hello');intro();go('#hello')};
  window.routeHello=instant=>{window.setPage('hello',instant);if(!instant)intro()};
  $('#home').addEventListener('click',()=>{if(scr.dataset.page==='hello')goHome()});
  addEventListener('keydown',e=>{
    if(e.key!=='Escape'||scr.dataset.page!=='hello'||document.getElementById('boot'))return;
    if(/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)){e.target.blur();return}
    goHome();
  });
  if(location.hash.indexOf('#hello')===0)window.routeHello(true);
})();

