// ===== Print résumé: a dark one-page sheet built from resume.js, in the site's own look =====
(function(){
  const el=(t,c,x)=>{const e=document.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e};
  const chips=t=>t.replace(/\.$/,'').split(/,|\|/).map(x=>x.trim()).filter(Boolean);
  const chipRow=list=>{const d=el('div','r-chips');list.forEach(x=>d.append(el('span','r-chip',x)));return d};
  const R=el('section');R.id='resume';
  // header: name and role on the left, contact lines on the right
  const hd=el('div','r-head'),l=el('div');
  l.append(el('h1',null,RESUME.name),el('p','r-role',RESUME.role));
  const ct=el('div','r-ct');
  RESUME.contact.concat([['GitHub',CONTACT.github],['LinkedIn',CONTACT.linkedin]]).forEach(r=>{const d=el('div');d.append(el('b',null,r[0]),el('span',null,r[1]));ct.append(d)});
  hd.append(l,ct);R.append(hd);
  // body: timeline on the left, details on the right
  const g=el('div','r-grid'),L=el('div'),Rt=el('div');
  L.append(el('div','r-lab','route · projects and education'));
  const tl=el('div','r-tl');
  RESUME.projects.slice().reverse().concat(RESUME.education).forEach(x=>{
    const n=el('div','r-node'),top=el('div','r-top'),h=el('h3',null,x.title);
    if(x.kind)h.append(el('span','r-badge',x.kind));
    top.append(h,el('span','r-when',x.when||''));n.append(top);
    if(x.place)n.append(el('div','r-sub',x.place));
    if(x.points&&x.points.length){const ul=el('ul');x.points.forEach(p=>ul.append(el('li',null,p)));n.append(ul)}
    if(x.tags&&x.tags.length)n.append(chipRow(x.tags));
    tl.append(n);
  });
  L.append(tl);
  const box=(lab,node)=>{const b=el('div','r-box');b.append(el('div','r-lab',lab),node);Rt.append(b)};
  box('summary',el('p',null,RESUME.summary));
  RESUME.extra.forEach(r=>{
    if(/^technical/i.test(r[0])){
      const wrap=el('div'),re=/([^,()]+?)\s*\(([^)]*)\)/g;let m,found=false;
      while((m=re.exec(r[1]))){found=true;const gp=el('div','r-group');gp.append(el('b',null,m[1].trim()),chipRow(chips(m[2])));wrap.append(gp)}
      box(r[0].toLowerCase(),found?wrap:el('p',null,r[1]));
    }else box(r[0].toLowerCase(),chipRow(chips(r[1])));
  });
  g.append(L,Rt);R.append(g);
  // footer
  const ft=el('div','r-foot');
  ft.append(el('span',null,(RESUME.contact.find(c=>/email/i.test(c[0]))||[,''])[1]));
  if(/^https?:/.test(location.protocol))ft.append(el('span',null,'interactive version · '+location.host+location.pathname.replace(/index\.html$/,'')));
  R.append(ft);
  document.body.appendChild(R);
  // the saved PDF gets a sensible file name
  const t0=document.title;
  addEventListener('beforeprint',()=>{document.title=RESUME.name+' - Resume'});
  addEventListener('afterprint',()=>{document.title=t0});
})();
